mapper.update:
update refund
set status = #{status}, channel_refund_no = #{channelRefundNo}, finished_at = #{finishedAt}
where refund_no = #{refundNo} and status = #{expectStatus}

update refund
set status = #{status}, fail_reason = #{failReason}, finished_at = #{finishedAt}, active_key = null
where refund_no = #{refundNo} and status = #{expectStatus}

update refund
set status = #{status}, audited_by = #{auditedBy}, audited_by_id = #{auditedById},
    audited_at = #{auditedAt}
where refund_no = #{refundNo} and status = #{expectStatus}
